INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('7', '3', 'PHC-2026-0007', 'Public Hearing on Proposed Ordinance No. ORD-2026-0003: Manila Web-Based Public Hearing and Consultation Management System', '1', '1', 'Session Hall, Manila City Hall', '2026-10-05', '2026-10-05', '09:00:00', '12:00:00', 'Upcoming', 'The City Council Committee on Laws and Ordinances hereby convenes this public hearing to gather formal citizen inputs, sectoral perspectives, and stakeholder recommendations on Proposed Ordinance No. ORD-2026-0003: \"An Ordinance Establishing a Web-Based Public Hearing and Consultation Management System for the City of Manila to Improve Public Participation, Transparency, and Legislative Consultation Processes.\"\n\nAgenda & Objectives:\n1. Deliberate on digital accessibility standards and citizen testimony mechanisms.\n2. Review legislative notification timelines and hybrid session protocols.\n3. Receive position papers from civil society, barangay leaders, and academic sectors.\n4. Address data privacy and records management in public consultations.\n\nAll registered attendees will be recognized during the open floor deliberation.', '2026-09-19 23:57:17', '2026-10-04 17:00:00', '150', 'https://meet.google.com/lph-hearing-2026', 'Public', '1', '2026-09-19 23:57:17', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('8', '1', 'PHC-2026-0008', 'Public Hearing on the Comprehensive Solid Waste Management and Segregation Ordinance of 2026', '1', '4', 'Session Hall, Manila City Hall', '2026-10-08', '2026-10-08', '09:00:00', '12:00:00', 'Upcoming', 'Public hearing on mandatory household and commercial waste segregation at source, penalty schedules for improper dumping, and material recovery facility (MRF) expansion in all 897 barangays of Manila.\n\nKey Topics:\n1. Barangay-level color-coded waste bin enforcement.\n2. Collection schedule rationalization and bio-waste composting.\n3. Incentives for zero-waste community initiatives.', '2026-09-20 05:30:39', '2026-10-07 17:00:00', '120', 'https://meet.google.com/env-waste-hearing-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('9', '2', 'PHC-2026-0009', 'Stakeholder Consultation on Public Transport Modernization and Tricycle Route Rationalization', '4', '7', 'Bulwagang Villegas, 2nd Floor, Manila City Hall', '2026-10-12', '2026-10-12', '13:30:00', '17:00:00', 'Upcoming', 'Consultation with jeepney and tricycle operators federations (TODA), commuter welfare groups, and traffic enforcement bureaus regarding proposed corridor routes and designated passenger loading bays.\n\nAgenda:\n1. Route realignment along secondary arteries.\n2. Fare matrix harmonization and PWD/Student discount compliance.\n3. Driver road safety certification programs.', '2026-09-20 05:30:39', '2026-10-11 17:00:00', '80', 'https://meet.google.com/transpo-hearing-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('10', '3', 'PHC-2026-0010', 'Committee Hearing on the Annual City Budget Allocation for Healthcare and Hospital Modernization', '2', '2', 'Committee Room 1, Legislative Building, Manila City Hall', '2026-10-15', '2026-10-15', '10:00:00', '14:00:00', 'Upcoming', 'Deliberation by the Committee on Appropriations and Finance on the FY 2027 health budget, medical assistance fund distribution, and medical equipment procurement for Manila\'s six district hospitals.\n\nPoints of Discussion:\n1. Line-item hospital modernization budget breakdown.\n2. Subsidized medicines inventory and distribution tracking.\n3. Healthcare worker hazard pay and retention programs.', '2026-09-20 05:30:39', '2026-10-14 17:00:00', '60', 'https://meet.google.com/finance-health-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('11', '8', 'PHC-2026-0011', 'Town Hall Consultation on Urban Drainage Rehabilitation and Flood Prevention in Flood-Prone Districts', '5', '5', 'Tondo Sports Complex, District 1, Manila', '2026-10-19', '2026-10-19', '14:00:00', '17:30:00', 'Upcoming', 'Grassroots town hall consultation with residents and barangay officials of Districts 1, 2, and 5 regarding ongoing pumping station upgrades, drainage declogging schedules, and community flood-risk mitigation protocols.\n\nProgram:\n1. Presentation of engineering blueprints by City Engineer\'s Office.\n2. Open floor for community resident concerns and flood hot-spots.\n3. Coordination protocols with MMDA for major pumping stations.', '2026-09-20 05:30:39', '2026-10-18 17:00:00', '250', 'https://meet.google.com/infra-flood-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('12', '3', 'PHC-2026-0012', 'Public Hearing on Digital Education and Student Internet Connectivity Support in Public Schools', '1', '6', 'Conference Hall B, Manila City Library', '2026-10-22', '2026-10-22', '09:30:00', '12:30:00', 'Upcoming', 'Deliberation on municipal subsidies for free high-speed campus Wi-Fi, digital learning module distribution, and computer laboratory enhancements across Manila public elementary and secondary schools.\n\nObjectives:\n1. Bridge the digital divide for indigent learners.\n2. Ensure cybersecurity and child online safety filters on city school networks.\n3. Solicit inputs from Parent-Teacher Associations (PTA) and educators.', '2026-09-20 05:30:39', '2026-10-21 17:00:00', '100', 'https://meet.google.com/edu-connectivity-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('13', '10', 'PHC-2026-0013', 'Special Hearing on Public Safety, Night Market Regulations, and Micro-Vendor Livelihood Protection', '6', '8', 'Session Hall, Manila City Hall', '2026-10-26', '2026-10-26', '13:00:00', '16:30:00', 'Upcoming', 'Joint special deliberation with hawkers, peace and order councils, and barangay officials on designated night market perimeters, sanitation requirements, and security camera installation mandates.\n\nAgenda:\n1. Clear zoning for sidewalk vending without impeding pedestrian flow.\n2. Waste collection fees and sanitary food handling permits.\n3. Installation of monitored CCTV systems along vendor corridors.', '2026-09-20 05:30:39', '2026-10-25 17:00:00', '150', 'https://meet.google.com/safety-vendor-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('14', '1', 'PHC-2026-0014', 'Public Consultation on Community Food Security and Urban Agriculture Development Ordinance', '3', '10', 'Mehan Garden Pavilion, Ermita, Manila', '2026-10-29', '2026-10-29', '09:00:00', '12:00:00', 'Upcoming', 'Consultation on establishing communal vertical gardens in vacant city lots, tax incentives for rooftop farming in commercial buildings, and farm-to-barangay direct retail pop-ups to keep food affordable.\n\nKey Highlights:\n1. Barangay seed bank and organic fertilizer subsidies.\n2. Partnership with state universities for urban farming technology.\n3. Direct marketplace access for local producers.', '2026-09-20 05:30:39', '2026-10-28 17:00:00', '120', 'https://meet.google.com/trade-agriculture-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('15', '11', 'PHC-2026-0015', 'Public Hearing on Comprehensive Healthcare Support and Nutrition Programs for Senior Citizens', '1', '3', 'Session Hall, Manila City Hall', '2026-11-03', '2026-11-03', '09:00:00', '12:00:00', 'Upcoming', 'Review of ordinance granting free maintenance medicine delivery, quarterly geriatric checkups, and specialized dietary assistance to indigent senior citizens in all city districts.\n\nDeliberation Areas:\n1. Door-to-door medicine logistics in coordination with OSCA.\n2. Specialized mobile clinic deployments in densely populated barangays.\n3. Healthcare budget earmarks for chronic illness treatments.', '2026-09-20 05:30:39', '2026-11-02 17:00:00', '150', 'https://meet.google.com/health-seniors-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
INSERT INTO `hearings` (`id`, `legislative_item_id`, `reference_number`, `title`, `hearing_type_id`, `committee_id`, `venue`, `hearing_date`, `end_date`, `hearing_time`, `end_time`, `status`, `description`, `created_at`, `registration_deadline`, `maximum_participants`, `meeting_link`, `visibility`, `created_by`, `updated_at`, `cancelled_at`, `cancellation_reason`) VALUES ('16', '3', 'PHC-2026-0016', 'Stakeholder Consultation on Barangay Social Welfare Assistance and Solo Parent Welfare Protection', '4', '9', 'Social Hall, Manila Department of Social Welfare, Arroceros', '2026-11-06', '2026-11-06', '13:30:00', '16:30:00', 'Upcoming', 'Direct consultation with solo parents associations, barangay VAWC officers, and DSWD representatives on expanding educational vouchers, emergency crisis intervention funds, and mental wellness centers.\n\nAgenda:\n1. Implementation guidelines for Republic Act No. 11861 at city level.\n2. Daycare center operating hour extensions for working solo parents.\n3. Livelihood seed capital grant mechanics.', '2026-09-20 05:30:39', '2026-11-05 17:00:00', '100', 'https://meet.google.com/social-soloparent-2026', 'Public', '1', '2026-09-20 05:30:39', NULL, NULL);
